// Test fee split truncation bias
pragma solidity 0.8.24;
import 'forge-std/Test.sol';
import {FixedHelper} from 'lbamm-pool-type-fixed/src/libraries/FixedHelper.sol';
import {FullMath} from 'lbamm-core/src/libraries/FullMath.sol';

contract FeeSplitBiasTest is Test {
    function test_lpFeeSplitBiasesInputHeight() public pure {
        // Setup: lpFeeAmount=10, amountOutFilledByOutputHeight=3, amountOut=10
        // mulDiv(10, 3, 10) = 3 (exact, no bias here)
        // lpFeeAmount=10, amountOutFilledByOutputHeight=3, amountOut=7
        // mulDiv(10, 3, 7) = 4 (rounds down from 4.28)
        // inputHeight gets 10 - 4 = 6 (vs proportional 5.71)
        uint256 lpFeeAmount = 10;
        uint256 outputFilled = 3;
        uint256 totalOut = 7;
        uint256 outputHeapFee = FullMath.mulDiv(lpFeeAmount, outputFilled, totalOut);
        uint256 inputHeapFee = lpFeeAmount - outputHeapFee;
        // Proportional: inputHeight should get 10 * (7-3)/7 = 5.71 -> 5 or 6
        // inputHeapFee should be <= 6
        assertEq(outputHeapFee + inputHeapFee, lpFeeAmount, 'fees must sum to total');
        // Assert: output height gets floor(proportional), input gets ceil
        assertTrue(inputHeapFee * totalOut >= (totalOut - outputFilled) * lpFeeAmount, 'input gets >= proportional');
    }
}

